import java.io.*;
import java.util.*;

public class Main {
    static int M, K;
    static int[] parent, size, levelFlag, pow;
    static long[] sum, ans;
    static ArrayList<Integer>[] lists;
    static boolean[] active;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        M = Integer.parseInt(st.nextToken());
        K = N * M;
        pow = new int[K];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < M; j++) {
                pow[i * M + j] = Integer.parseInt(st.nextToken());
            }
        }

        Integer[] order = new Integer[K];
        for (int i = 0; i < K; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(pow[a], pow[b]));

        parent = new int[K];
        size = new int[K];
        sum = new long[K];
        levelFlag = new int[K];
        ans = new long[K];
        active = new boolean[K];
        lists = new ArrayList[K];
        Arrays.fill(levelFlag, -1);

        for (int idx : order) {
            int p = pow[idx];
            active[idx] = true;
            parent[idx] = idx;
            size[idx] = 1;
            sum[idx] = p;
            levelFlag[idx] = p;
            lists[idx] = new ArrayList<>();
            lists[idx].add(idx);

            if (idx >= M) {
                int nb = idx - M;
                if (active[nb]) union(idx, nb, p);
            }
            if (idx + M < K) {
                int nb = idx + M;
                if (active[nb]) union(idx, nb, p);
            }
            if (idx % M != 0) {
                int nb = idx - 1;
                if (active[nb]) union(idx, nb, p);
            }
            if (idx % M != M - 1) {
                int nb = idx + 1;
                if (active[nb]) union(idx, nb, p);
            }
        }

        for (int i = 0; i < K; i++) {
            if (lists[i] != null) {
                finalize(i);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (j > 0) sb.append(' ');
                sb.append(ans[i * M + j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static void finalize(int root) {
        if (lists[root] != null) {
            long val = sum[root];
            for (int cell : lists[root]) {
                ans[cell] = val;
            }
            lists[root].clear();
            lists[root] = null;
        }
    }

    static int union(int a, int b, int p) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return ra;

        if (levelFlag[ra] != p && sum[ra] < p) finalize(ra);
        if (levelFlag[rb] != p && sum[rb] < p) finalize(rb);

        int newRoot, other;
        if (size[ra] < size[rb]) {
            newRoot = rb;
            other = ra;
        } else {
            newRoot = ra;
            other = rb;
        }

        parent[other] = newRoot;
        size[newRoot] += size[other];
        sum[newRoot] += sum[other];
        levelFlag[newRoot] = p;

        ArrayList<Integer> listNew = lists[newRoot];
        ArrayList<Integer> listOther = lists[other];
        if (listNew == null) {
            lists[newRoot] = listOther;
        } else if (listOther != null) {
            if (listNew.size() < listOther.size()) {
                listOther.addAll(listNew);
                lists[newRoot] = listOther;
            } else {
                listNew.addAll(listOther);
            }
        }
        lists[other] = null;
        return newRoot;
    }
}
